export function findIl2CppDumperBin(root: string): { exe: string; exists: boolean } {
  const exe = join(root, 'vendor', 'il2cppdumper', 'Il2CppDumper.exe');
  let exists = false; try { exists = existsSync(exe); } catch { exists = false; }
  return { exe, exists };
}
export function il2cppdumperStatus(root: string): string {
  const b = findIl2CppDumperBin(root);
  return ['Il2CppDumper ' + IL2CPPDUMPER_VERSION + ' ' + UPSTREAM, 'exe=' + b.exe + ' exists=' + b.exists].join('\n');
}
export function runIl2CppDumper(root: string, so: string, meta: string, out: string): string {
  const b = findIl2CppDumperBin(root);
  if (!b.exists) return 'ERR|Il2CppDumper.exe missing ' + b.exe;
  if (!so || !meta) return 'ERR|need so + meta (libil2cpp.so + global-metadata.dat)';
  try {
    const r = spawnSync(b.exe, [so, meta, out || (root + '/logs/il2cppdumper-new')], { encoding: 'utf8', timeout: 180000 });
    return 'code=' + String(r.status) + '\nout=' + String(r.stdout || '').slice(0, 6000) + '\nerr=' + String(r.stderr || '').slice(0, 2000);
  } catch (e: any) { return 'ERR|' + (e?.message || String(e)); }
